// Creates a placeholder amplify_outputs.json when none exists, so the app can
// type-check, test and run with fixtures before a backend is deployed.
// The real file is generated by `npx ampx sandbox` or `npx ampx pipeline-deploy`.
import { existsSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'

const target = resolve(process.cwd(), 'amplify_outputs.json')

if (!existsSync(target)) {
  writeFileSync(target, JSON.stringify({ version: '1.4' }, null, 2) + '\n')
  console.log('[ensure-amplify-outputs] wrote placeholder amplify_outputs.json (no backend yet)')
}
